#include <pro_ext.h>
FAR Example(ParamBlk FAR *parm)
{
   int i;
   WHANDLE wh;
   char String[256];
   wh = _WOpen(2,2,20,70,WEVENT | CLOSE,WINDOW_SCHEME,(Scheme FAR *) 0,
      WO_SYSTEMBORDER);
   _WShow(wh);
   for (i = 0; i < 255; i++)
